import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Sylwester Golonka'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'sylwester.golonka@nokia.com'


class SshStatus(GenericEMSSIMCommand):
    """Sshstatus command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Sshstatus command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SshStatus, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = False
        self.session = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "ssh_status"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_ssh_status(line)
                self._parse_ssh_details(line)
                self._parse_interactive_session(line)
                self._parse_session(line)
                self._parse_warning(line)
            except ParsingDone:
                pass
        return super(SshStatus, self).on_new_line(line, is_full_line)

    _re_ssh_status = re.compile(r'SSH\sService\sStatus\sis\s(?P<STATUS>\w+)')

    def _parse_ssh_status(self, line):
        if self._regex_helper.search_compiled(SshStatus._re_ssh_status, line):
            self.current_ret["status"] = self._regex_helper.group("STATUS")
            raise ParsingDone

    _re_parse_warning = re.compile(r'WARNING:\s(?P<WARNING>.*)')

    def _parse_warning(self, line):
        if self._regex_helper.search_compiled(SshStatus._re_parse_warning, line):
            self.current_ret['status'] = self._regex_helper.group("WARNING")
            raise ParsingDone

    _re_ssh_details = re.compile(r'\|\s(?P<SIZE>\d+)\s(?P<KEY>[a-zA-Z\d:]*)\s*(?P<PROMPT>.*)\s\(.*\)')

    def _parse_ssh_details(self, line):
        if self._regex_helper.search_compiled(SshStatus._re_ssh_details, line):
            self.current_ret["SIZE"] = self._regex_helper.group("SIZE")
            self.current_ret["KEY"] = self._regex_helper.group("KEY")
            self.current_ret["PROMPT"] = self._regex_helper.group("PROMPT")
            raise ParsingDone

    _re_interactive_session = re.compile(r'(?P<SESSION>NON INTERACTIVE SESSION|INTERACTIVE SESSION)')

    def _parse_interactive_session(self, line):
        if self._regex_helper.search_compiled(SshStatus._re_interactive_session, line):
            self.session = self._regex_helper.group("SESSION")
            raise ParsingDone

    _re_session = re.compile(r'\|\s(?P<SESSION>.*)')

    def _parse_session(self, line):
        if self.session:
            if self._regex_helper.search_compiled(SshStatus._re_session, line):
                self.current_ret[self.session] = self._regex_helper.group('SESSION')
                self.session = False
            raise ParsingDone


